import { workspaceAspectKey, } from "../../engine/build/context.js";
import { expr, isCanonicalTsLabel, sanitizeName, scopedResourceLabel, tsLabelToTfLabel, } from "../../engine/tf/index.js";
import { filterToTf } from "../access-policy/to-tf.js";
